package handler

import (
	"context"
	"crypto/sha1"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// The frozen inventories were authored from the complete upstream originals,
// independently of the development handler. Never regenerate from its output.
func TestQBasicTwoWholePinnedOriginalDeclarationInventories(t *testing.T) {
	root := os.Getenv("SCRIPTHOLD_REAL_QBASIC_TWO_WHOLE_ROOT")
	if root == "" {
		t.Skip("two whole pinned QBasic originals not configured")
	}
	var inventory struct {
		Files []struct {
			File     string `json:"file"`
			Blob     string `json:"blob"`
			Bytes    int64  `json:"bytes"`
			Expected []struct {
				Name             string                                           `json:"name"`
				Kind             string                                           `json:"kind"`
				NativeKind       string                                           `json:"nativeKind"`
				QualifiedName    string                                           `json:"qualifiedName"`
				Owner            string                                           `json:"owner"`
				NameRange        struct{ Start, End struct{ Line, Column int } }  `json:"nameRange"`
				DeclarationRange struct{ Start, End struct{ Line, Column int } }  `json:"declarationRange"`
				SignatureRange   *struct{ Start, End struct{ Line, Column int } } `json:"signatureRange"`
				Signature        string                                           `json:"signature"`
			} `json:"expected"`
		} `json:"files"`
	}
	if err := json.Unmarshal([]byte(qbasicTwoWholeOracle), &inventory); err != nil {
		t.Fatal(err)
	}
	if len(inventory.Files) != 2 {
		t.Fatalf("invalid upstream file count: %d", len(inventory.Files))
	}
	h := NewHandler([]string{root})
	ctx := context.Background()
	total := 0
	for _, f := range inventory.Files {
		t.Run(f.File, func(t *testing.T) {
			path := filepath.Join(root, f.File)
			st, err := os.Lstat(path)
			if err != nil {
				t.Fatal(err)
			}
			if !st.Mode().IsRegular() || st.Size() != f.Bytes {
				t.Fatalf("pinned complete source changed: %+v", st)
			}
			original, err := os.ReadFile(path)
			if err != nil {
				t.Fatal(err)
			}
			hash := sha1.New()
			_, _ = fmt.Fprintf(hash, "blob %d%c", len(original), 0)
			_, _ = hash.Write(original)
			if hex.EncodeToString(hash.Sum(nil)) != f.Blob {
				t.Fatalf("whole-original Git blob differs: %s", f.File)
			}
			fail, out, err := h.SourceSymbols(ctx, nil, SourceSymbolsInput{Operation: "outline", Presentation: "detailed", Paths: []string{path}, Language: "qbasic", Encoding: "utf-8", IncludeSignatures: true, MaxFiles: 1, MaxSymbols: 256})
			if err != nil || fail != nil || !out.CoverageComplete || out.Truncated || out.FilesParsed != 1 || len(out.Files) != 1 || len(out.Symbols) != len(f.Expected) {
				t.Fatalf("whole-source declaration coverage expected=%d got=%d fail=%+v err=%v", len(f.Expected), len(out.Symbols), fail, err)
			}
			if out.Files[0].SourceFingerprint == "" || out.Files[0].SourceBytes != f.Bytes {
				t.Fatalf("bad source fingerprint or byte count %+v", out.Files[0])
			}
			byLocation := make(map[string]int, len(out.Symbols))
			seen := make(map[string]bool, len(out.Symbols))
			for i, s := range out.Symbols {
				loc := fmt.Sprintf("%d:%d", s.NameRange.Start.Line, s.NameRange.Start.Column)
				if _, ok := byLocation[loc]; ok {
					t.Errorf("duplicate location: %s", loc)
				}
				byLocation[loc] = i
				if s.ID == "" || seen[s.ID] {
					t.Errorf("missing or duplicate symbol ID %s", loc)
				}
				seen[s.ID] = true
			}
			for _, e := range f.Expected {
				loc := fmt.Sprintf("%d:%d", e.NameRange.Start.Line, e.NameRange.Start.Column)
				i, ok := byLocation[loc]
				if !ok {
					t.Errorf("missing authored declaration %s at %s", e.Name, loc)
					continue
				}
				s := out.Symbols[i]
				if s.Name != e.Name || string(s.Kind) != e.Kind || s.NativeKind != e.NativeKind || s.QualifiedName != e.QualifiedName || s.ParentQualifiedName != e.Owner ||
					s.NameRange.Start.Line != e.NameRange.Start.Line || s.NameRange.Start.Column != e.NameRange.Start.Column || s.NameRange.End.Line != e.NameRange.End.Line || s.NameRange.End.Column != e.NameRange.End.Column ||
					s.DeclarationRange.Start.Line != e.DeclarationRange.Start.Line || s.DeclarationRange.Start.Column != e.DeclarationRange.Start.Column || s.DeclarationRange.End.Line != e.DeclarationRange.End.Line || s.DeclarationRange.End.Column != e.DeclarationRange.End.Column {
					t.Errorf("authored full original mismatch %s at %s: %+v", e.Name, loc, s)
				}
				if e.SignatureRange != nil && (s.SignatureRange == nil || s.SignatureRange.Start.Line != e.SignatureRange.Start.Line ||
					s.SignatureRange.Start.Column != e.SignatureRange.Start.Column || s.SignatureRange.End.Line != e.SignatureRange.End.Line ||
					s.SignatureRange.End.Column != e.SignatureRange.End.Column || s.Signature != e.Signature) {
					t.Errorf("authored signature mismatch %s: %+v", e.Name, s)
				}
			}
			first := f.Expected[0].Name
			fail, found, err := h.SourceSymbols(ctx, nil, SourceSymbolsInput{Operation: "find", Paths: []string{path}, Language: "qbasic", Encoding: "utf-8", Query: first, Match: "exact", MaxFiles: 1, MaxSymbols: 256})
			var id string
			for _, s := range found.Symbols {
				if s.Name == first {
					id = s.ID
				}
			}
			if err != nil || fail != nil || id == "" {
				t.Fatalf("whole-original exact find %s: %+v %v", first, fail, err)
			}
			fail, shown, err := h.SourceSymbols(ctx, nil, SourceSymbolsInput{Operation: "show", Path: path, Language: "qbasic", Encoding: "utf-8", SymbolID: id, SourceFingerprint: out.Files[0].SourceFingerprint, MaxBytes: 8192})
			if err != nil || fail != nil || shown.Show == nil || !strings.Contains(shown.Show.Text, first) {
				t.Fatalf("fingerprint-bound original show %s %+v %v", first, fail, err)
			}
			fail, q, err := h.SourceQuery(ctx, nil, SourceQueryInput{Operation: "search", Mode: "structural", Paths: []string{path}, Language: "qbasic", Encoding: "utf-8", Query: first, Match: "exact", MaxFiles: 1, MaxResults: 256})
			matched := false
			if q.Search != nil {
				for _, m := range q.Search.Matches {
					if m.SymbolID == id && m.Name == first {
						matched = true
					}
				}
			}
			if err != nil || fail != nil || !matched {
				t.Fatalf("original structural search %s %+v %v", first, fail, err)
			}
			for _, negative := range []string{"ghostQBasicSymbol", "CONST", "TYPE"} {
				fail, none, err := h.SourceSymbols(ctx, nil, SourceSymbolsInput{Operation: "find", Paths: []string{path}, Language: "qbasic", Encoding: "utf-8", Query: negative, Match: "exact", MaxFiles: 1, MaxSymbols: 256})
				if err != nil || fail != nil || len(none.Symbols) != 0 {
					t.Errorf("invented declaration %s: %+v %v", negative, fail, err)
				}
			}
			total += len(f.Expected)
		})
	}
	if total != 117 {
		t.Fatalf("incomplete source-first inventory: %d/117", total)
	}
}

